<?php $pageTitle='Seating allocation'; ?>
<?php if($allocation['status']==='draft'):?><section class="panel no-print"><div class="form-section-heading"><p class="eyebrow">Manual correction</p><h2>Move an assigned student</h2><p>Every correction is marked as a manual override and written to the audit trail.</p></div><form class="form-grid three" method="post" action="<?= e(url('seating/'.$allocation['id'].'/move')) ?>"><?= csrf_field() ?><label>Current assignment<select name="assignment_id" required><option value="">Select student</option><?php foreach($assignments as $item):?><option value="<?= (int)$item['id'] ?>" data-school="<?= (int)$item['school_id'] ?>" data-group="<?= e($item['group_key']) ?>"><?= e($item['roll_no_original'].' - '.$item['room_code'].'/'.$item['seat_label']) ?></option><?php endforeach;?></select></label><label>New vacant seat<select name="seat_id" required><option value="">Select seat</option><?php foreach($availableSeats as $seat):?><option data-school="<?= (int)$seat['school_id'] ?>" data-group="<?= e($seat['group_key']) ?>" value="<?= (int)$seat['id'] ?>"><?= e($seat['room_code'].' / '.$seat['seat_label']) ?></option><?php endforeach;?></select></label><label>Reason<input name="reason" required placeholder="Operational correction"><button class="secondary-button">Move student</button></label></form></section><?php endif;?>
<?php if($unallocated):?><section class="panel table-panel no-print"><div class="form-section-heading"><p class="eyebrow">Capacity exception report</p><h2>Unallocated students</h2><p>Assign a newly available vacant seat or include these students in the exported exception report.</p></div><div class="table-scroll"><table><thead><tr><th>Roll number</th><th>Name</th><th>Programme</th><th>Paper</th><th>Resolution</th></tr></thead><tbody><?php foreach($unallocated as $item):?><tr><td><strong><?= e($item['roll_no_original']) ?></strong></td><td><?= e($item['name']) ?></td><td><?= e($item['programme_code']) ?></td><td><?= e($item['course_code']) ?></td><td><?php if($allocation['status']==='draft'):?><form class="inline-form" method="post" action="<?= e(url('seating/'.$allocation['id'].'/assign-unallocated')) ?>"><?= csrf_field() ?><input type="hidden" name="unallocated_id" value="<?= (int)$item['id'] ?>"><select name="seat_id" required><option value="">Vacant seat</option><?php foreach($availableSeats as $seat):if((int)$seat['school_id']!==(int)$item['school_id']||($seat['group_key']!==''&&$seat['group_key']!==$item['group_key']))continue;?><option data-school="<?= (int)$seat['school_id'] ?>" data-group="<?= e($seat['group_key']) ?>" value="<?= (int)$seat['id'] ?>"><?= e($seat['room_code'].'/'.$seat['seat_label']) ?></option><?php endforeach;?></select><button class="text-button">Assign</button></form><?php else:?>Requires a new allocation version<?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section><?php endif;?>
<section class="page-heading no-print"><div><p class="eyebrow">Version <?= (int)$allocation['version_no'] ?></p><h1><?= e($allocation['cycle_name']) ?></h1><p><?= e(date('d F Y',strtotime($allocation['exam_date'])).' - '.$allocation['shift_name']) ?></p></div><div class="heading-actions"><a class="secondary-button" href="<?= e(url('seating/'.$allocation['id'].'/export.xlsx')) ?>">Download Excel</a><a class="secondary-button" href="javascript:window.print()">Print all rooms</a><?php if($allocation['status']==='draft'):?><form method="post" action="<?= e(url('seating/'.$allocation['id'].'/publish')) ?>"><?= csrf_field() ?><button class="primary-button" <?= !$validation['valid']?'disabled':'' ?>>Publish allocation</button></form><?php endif;?></div></section><?php if($success):?><div class="alert success no-print"><?= e($success) ?></div><?php endif;?><?php if($error):?><div class="alert error no-print"><?= e($error) ?></div><?php endif;?><section class="validation-strip no-print"><strong><?= $validation['valid']?'Validation passed':'Validation failed' ?></strong><?php foreach($validation as $name=>$value):if($name==='valid')continue;?><span><?= e(str_replace('_',' ',$name)) ?>: <?= (int)$value ?></span><?php endforeach;?></section><link rel="stylesheet" href="<?= e(url('assets/css/seating-document.css')) ?>">
<?php if(($document['rules']['mode']??'')==='paired_cohorts'):?><section class="panel pairing-rules-summary no-print"><h2>Saved branch/batch pairings</h2><?php foreach($document['rules']['pairings'] as $pair):?><p><strong><?= e($document['rules']['cohorts'][$pair['left']]['label']) ?></strong> with <strong><?= e($document['rules']['cohorts'][$pair['right']]['label']) ?></strong></p><?php endforeach;?></section><?php endif;?>
<div class="seating-document-scroll"><?php foreach($document['rooms'] as $room):require BASE_PATH.'/resources/views/seating/room-sheet.php';endforeach;?></div>


<script>(()=>{const student=document.querySelector('select[name="assignment_id"]');if(!student)return;const seats=student.closest('form').querySelector('select[name="seat_id"]');const update=()=>{const school=student.selectedOptions[0]?.dataset.school;seats.value='';for(const option of seats.options){if(!option.value)continue;option.hidden=!school||option.dataset.school!==school||(option.dataset.group!==''&&option.dataset.group!==student.selectedOptions[0]?.dataset.group);option.disabled=option.hidden;}};student.addEventListener('change',update);update();})();</script>
